namespace App\Tools\TaxReformSimulator\Domain\Services; use App\Core\Money\{Money,Percentage}; use App\Core\Tools\Calculation\Data\{CalculationMemory,CalculationMemoryStep,ToolCalculationResult,ToolCalculationSummaryItem,ToolCalculationWarning}; use App\Core\Tools\Calculation\Enums\ToolCalculationWarningLevel; use App\Core\Tools\Contracts\{ToolCalculationInput,ToolCalculator}; use App\Tools\TaxReformSimulator\Application\Data\CalculationInput; use App\Tools\TaxReformSimulator\Domain\Rules\ConsumptionTaxTransitionRule; use InvalidArgumentException; final readonly class Calculator implements ToolCalculator { public function __construct(private ConsumptionTaxTransitionRule $rule){} private function pct(int $m):Percentage{$w=intdiv($m,1000000);$f=str_pad((string)($m%1000000),6,'0',STR_PAD_LEFT);return Percentage::fromString($w.'.'.$f);} public function calculate(ToolCalculationInput $input):ToolCalculationResult{if(!$input instanceof CalculationInput)throw new InvalidArgumentException('Entrada inválida.');$rev=Money::fromDecimal($input->revenue);$lf=Percentage::fromString($input->legacyFederalRate);$ls=Percentage::fromString($input->legacySubnationalRate);$cbsRef=Percentage::fromString($input->cbsReferenceRate);$ibsRef=Percentage::fromString($input->ibsReferenceRate);$credit=Percentage::fromString($input->creditBasePercent);$tr=$this->rule->forYear($input->year);$creditBase=$rev->percentage($credit);$lfAmt=$rev->percentage($this->pct(intdiv($lf->millionthsOfPercent()*$tr['lf'],100)));$lsAmt=$rev->percentage($this->pct(intdiv($ls->millionthsOfPercent()*$tr['ls'],100)));if($input->year===2026){$cbs=Percentage::fromString('0.9');$ibs=Percentage::fromString('0.1');}elseif($input->year<=2028){$cbs=$this->pct(max(0,$cbsRef->millionthsOfPercent()-100000));$ibs=Percentage::fromString('0.1');}else{$cbs=$cbsRef;$ibs=$this->pct(intdiv($ibsRef->millionthsOfPercent()*$tr['ibs'],100));}$cbsAmt=Money::fromMinor(max(0,$rev->percentage($cbs)->minorAmount()-$creditBase->percentage($cbs)->minorAmount()));$ibsAmt=Money::fromMinor(max(0,$rev->percentage($ibs)->minorAmount()-$creditBase->percentage($ibs)->minorAmount()));$total=$lfAmt->add($lsAmt)->add($cbsAmt)->add($ibsAmt);$base=$rev->percentage($lf)->add($rev->percentage($ls));$delta=$total->subtract($base);$mem=new CalculationMemory('1.0.0',[new CalculationMemoryStep('legacy','Legado remanescente','carga efetiva × percentual da transição',['year'=>$input->year],$lfAmt->add($lsAmt)->minorAmount()),new CalculationMemoryStep('new','CBS + IBS líquidos','débitos menos créditos aproximados',[],$cbsAmt->add($ibsAmt)->minorAmount())],[],['Alíquotas futuras de referência são informadas pelo usuário; não são inventadas pela ferramenta.'],true);return new ToolCalculationResult('simulador-reforma-tributaria-consumo','1.0.0',[new ToolCalculationSummaryItem('baseline','Carga atual informada',$base->formatPtBr()),new ToolCalculationSummaryItem('transition','Carga simulada '.$input->year,$total->formatPtBr()),new ToolCalculationSummaryItem('delta','Diferença estimada',$delta->formatPtBr()),new ToolCalculationSummaryItem('new_taxes','CBS + IBS líquidos',$cbsAmt->add($ibsAmt)->formatPtBr())],['year'=>$input->year,'cbs_rate'=>$cbs->toDecimalString(),'ibs_rate'=>$ibs->toDecimalString(),'legacy_federal_remaining_percent'=>$tr['lf'],'legacy_subnational_remaining_percent'=>$tr['ls'],'transition_note'=>$tr['note'],'rule_version'=>ConsumptionTaxTransitionRule::VERSION],[new ToolCalculationWarning('transition',$tr['note'],ToolCalculationWarningLevel::Info),new ToolCalculationWarning('parametric','Não contempla regimes específicos, reduções, Imposto Seletivo, cashback ou classificação jurídica das operações.',ToolCalculationWarningLevel::Info)],calculationMemory:$mem);} }
